/* Assets vendus depuis le package solitaire95 — déclarations de modules
   non couvertes par les types Next (fonts, mp3). Les images (*.png) sont
   typées par next/image-types/global (StaticImageData) et normalisées en
   `.src` dans les index statiques. */

declare module "*.mp3" {
  const content: string;
  export default content;
}

declare module "*.woff" {
  const content: string;
  export default content;
}

declare module "*.woff2" {
  const content: string;
  export default content;
}

declare module "*.ttf" {
  const content: string;
  export default content;
}